fn no_adjacent_dups(xs: List[Int]) -> Bool
  requires true
  ensures true
  effects pure
  example no_adjacent_dups([]) == true
  example no_adjacent_dups([1]) == true
  example no_adjacent_dups([1, 2, 2, 3]) == false
  example no_adjacent_dups([1, 2, 3]) == true
{
  match xs {
    [] => true
    [h, ..t] => match t {
