fn dedupe_adjacent(xs: List[Int]) -> List[Int]
  requires true
  ensures length(result) <= length(xs)
  ensures no_adjacent_dups(result) == true
  effects pure
  example dedupe_adjacent([]) == []
  example dedupe_adjacent([1, 1, 2, 2, 2, 3, 1, 1]) == [1, 2, 3, 1]
  example dedupe_adjacent([1, 2, 3]) == [1, 2, 3]
  example dedupe_adjacent([5, 5, 5, 5]) == [5]
{
  match xs {
    [] => []
    [h, ..t] => match t {
      [] => [h]
      [h2, ..t2] =>
        if h == h2
        then dedupe_adjacent(t)
        else [h] ++ dedupe_adjacent(t)
    }
  }
}

def dedupe_adjacent(xs: list[int]) -> list[int]:
    result = []
    for x in xs:
        if not result or result[-1] != x:
            result.append(x)
    return result

def int_sqrt(n: int) -> int:
    if n < 2:
        return n
    lo, hi = 0, n
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return mid
        elif sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

def longest_run(xs: list[int]) -> int:
    if not xs:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(xs)):
        if xs[i] == xs[i - 1]:
            current += 1
            if current > longest:
                longest = current
        else:
            current = 1
    return longest

