fn merge_sorted(xs: List[Int], ys: List[Int]) -> List[Int]
  requires is_sorted(xs)
  requires is_sorted(ys)
  ensures is_sorted(result)
  ensures length(result) == length(xs) + length(ys)
  effects pure
  example merge_sorted([], []) == []
  example merge_sorted([1, 3, 5], [2, 4, 6]) == [1, 2, 3, 4, 5, 6]
  example merge_sorted([1, 1, 2], [1, 3]) == [1, 1, 1, 2, 3]
  example merge_sorted([], [1, 2]) == [1, 2]
  example merge_sorted([1, 2], []) == [1, 2]
{
  match xs {
    [] => ys
    [hx, ..tx] => match ys {
      [] => xs
      [hy, ..ty] =>
        if hx <= hy
        then [hx] ++ merge_sorted(tx, ys)
        else [hy] ++ merge_sorted(xs, ty)
    }
  }
}

def merge_sorted(xs: list[int], ys: list[int]) -> list[int]:
    result = []
    i, j = 0, 0
    len_xs, len_ys = len(xs), len(ys)

    while i < len_xs and j < len_ys:
        if xs[i] <= ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1

    while i < len_xs:
        result.append(xs[i])
        i += 1

    while j < len_ys:
        result.append(ys[j])
        j += 1

    return result

def most_frequent(xs: list[int]) -> int | None:
    if not xs:
        return None

    counts: dict[int, int] = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1

    best_value = None
    best_count = -1
    for value, count in counts.items():
        if count > best_count or (count == best_count and value < best_value):
            best_value = value
            best_count = count

    return best_value

