def nth(xs: list[int], i: int) -> int | None:
    if 0 <= i < len(xs):
        return xs[i]
    return None

def power(base: int, exp: int) -> int:
    if exp == 0:
        return 1
    result = 1
    for _ in range(exp):
        result *= base
    return result

def rotate_left(xs: list[int], k: int) -> list[int]:
    if not xs:
        return []
    n = len(xs)
    k = k % n
    return xs[k:] + xs[:k]

def second_largest(xs: list[int]) -> int | None:
    distinct = set(xs)
    if len(distinct) < 2:
        return None
    largest = max(distinct)
    distinct.remove(largest)
    return max(distinct)

