fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires true
  ensures length(result) == min_int(length(xs), length(ys))
  effects pure
  example zip_sum([], []) == []
  example zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33]
  example zip_sum([1, 2], [10, 20, 30]) == [11, 22]
  example zip_sum([1, 2, 3], [10]) == [11]
{
  match xs {
